head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getColumnUseEditFormat]<br/>Body Column 정보를 사용하여 특정 Column 의 useEditFormat 속성값을 반환합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 useEditFormat 속성값을 조회할 Body Column 의 인덱스를 설정할 수 있어야 합니다.",
        "columnInfo(필수) 파라미터의 Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "Body Column 이 inputType='calendar' 인 경우에 유효한 값을 반환합니다.",
        "파라미터에 해당하는 Body Column 의 useEditFormat 속성값을 true/false 로 반환해야 합니다.",
        "Body Column 의 inputType 속성값이 'calendar' 가 아니면 false 를 반환해야 합니다.",
        "파라미터가 유효하지 않으면 false 를 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Column 인덱스 - 0:calDate1(calendar, useEditFormat=true) / 1:calDate2(calendar, useEditFormat=false) / 2:txtName(text, 비-calendar) / 3:calDate3(calendar, useEditFormat=true, 숨김 setColumnVisible(3,false)). 숨김 Column 도 포함하여 인덱스가 부여됨. 데이터 Row 4개.\n[절차] columnInfo(인덱스) 선택 후 (getColumnUseEditFormat 실행) 클릭.\n[확인] 0=true / 1=false / 2=false(비-calendar) / 3=true(숨김 calendar) / 99=false(유효하지않음) 가 반환영역에 출력됨."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="calDate1" name="calDate1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="calDate2" name="calDate2" dataType="text"></w2:column>';
    strDlt += '<w2:column id="txtName" name="txtName" dataType="text"></w2:column>';
    strDlt += '<w2:column id="calDate3" name="calDate3" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "calDate1": "20260101", "calDate2": "20260201", "txtName": "노트북", "calDate3": "20260301" },
        { "calDate1": "20260102", "calDate2": "20260202", "txtName": "모니터", "calDate3": "20260302" },
        { "calDate1": "20260103", "calDate2": "20260203", "txtName": "키보드", "calDate3": "20260303" },
        { "calDate1": "20260104", "calDate2": "20260204", "txtName": "마우스", "calDate3": "20260304" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Header 4컬럼 + gBody) - Header inputType 은 text, gBody 가 실제 inputType
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:640px;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getColumnUseEditFormat 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol1" value="일자1(calendar useEditFormat=true)"></w2:column>';
    strTarget += '<w2:column width="160" style="" inputType="text" id="hcol2" value="일자2(calendar useEditFormat=false)"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="hcol3" value="품목(text)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="일자3(calendar 숨김)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    // index 0 : calDate1 (calendar, useEditFormat=true)
    strTarget += '<w2:column width="160" style="" inputType="calendar" calendarValueType="yearMonthDate" displayFormat="yyyy/MM/dd" useEditFormat="true" id="calDate1" dataList="calDate1"></w2:column>';
    // index 1 : calDate2 (calendar, useEditFormat=false)
    strTarget += '<w2:column width="160" style="" inputType="calendar" calendarValueType="yearMonthDate" displayFormat="yyyy/MM/dd" useEditFormat="false" id="calDate2" dataList="calDate2"></w2:column>';
    // index 2 : txtName (text, 비-calendar)
    strTarget += '<w2:column width="140" style="" inputType="text" id="txtName" dataList="txtName"></w2:column>';
    // index 3 : calDate3 (calendar, useEditFormat=true) - setColumnVisible(3,false) 로 숨김 -> 숨김 포함 인덱스 검증용
    strTarget += '<w2:column width="*" style="" inputType="calendar" calendarValueType="yearMonthDate" displayFormat="yyyy/MM/dd" useEditFormat="true" id="calDate3" dataList="calDate3"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 네번째 Column(calDate3, 인덱스 3) 숨김 -> 숨김 Column 포함 인덱스 검증용
    target1.setColumnVisible(3, false);
}



// getColumnUseEditFormat 조회 (메인 검증)
scwin.btn_getColumnUseEditFormat_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());

    // getColumnUseEditFormat : calendar Column 의 useEditFormat 속성값 반환
    // (calendar 아님 / 유효하지 않은 파라미터 는 모두 false)
    let result = target1.getColumnUseEditFormat(columnInfo);

    wf_body_bottom.getObj("scwin").setReturnValue("getColumnUseEditFormat(" + columnInfo + ") -> 반환값: " + result);
}
